/**
 * frontend/src/api_service.js - SERVICE API CORRIGÉ ET UNIFORMISÉ
 * Backend synchronisé avec StudentViewSet et AttendanceViewSet
 */

import authService, { api } from './auth_service';

/**
 * ======================
 * CONFIG
 * ======================
 */
const API_BASE_URL = 'http://localhost:8000/api';

/**
 * ======================
 * UTILS
 * ======================
 */
const cleanBase64 = (base64String) => {
  if (!base64String) return '';
  if (base64String.startsWith('data:')) {
    return base64String.split(',')[1];
  }
  return base64String;
};
const safeResponse = (response) => {
  if (!response?.data) {
    return {
      success: false,
      error: 'Empty response',
    };
  }

  return response.data;
};
/**
 * ======================
 * STUDENTS API
 * ======================
 */
export const studentsAPI = {
  /**
   * Enroll student from image
   */
  enrollFromImage: async (name, email, file) => {
    try {
      const reader = new FileReader();

      return new Promise((resolve, reject) => {
        reader.onload = async (event) => {
          try {
            const base64 = event.target.result;

            const response = await api.post('/students/enroll_from_image/api', {
              name,
              email: email || '',
              image_base64: cleanBase64(base64),
            });

            console.log('[STUDENTS][ENROLL] Success:', response.data);

            resolve({
              success: true,
              data: response.data,
            });
          } catch (error) {
            const message =
              error.response?.data?.error ||
              'Enrollment error';

            console.error('[STUDENTS][ENROLL] Error:', message);

            reject({
              success: false,
              error: message,
            });
          }
        };

        reader.onerror = () => {
          console.error('[STUDENTS][ENROLL] File read error');

          reject({
            success: false,
            error: 'File reading error',
          });
        };

        reader.readAsDataURL(file);
      });
    } catch (error) {
      console.error('[STUDENTS][ENROLL] Unexpected error:', error);

      return {
        success: false,
        error: 'Unexpected error during enrollment',
      };
    }
  },

  /**
   * Get all students
   */
  getAll: async () => {
    try {
      const response = await api.get('/students/');

      console.log('[STUDENTS][GET_ALL] Success');

      return {
        success: true,
        data: response.data,
      };
    } catch (error) {
      console.error('[STUDENTS][GET_ALL] Error:', error);

      return {
        success: false,
        error: 'Failed to fetch students',
      };
    }
  },

  /**
   * Search students
   */
  search: async (query) => {
    try {
      const response = await api.post('/students/search/', {
        query,
      });

      console.log('[STUDENTS][SEARCH] Success:', response.data);

      return {
        success: true,
        data: response.data,
      };
    } catch (error) {
      console.error('[STUDENTS][SEARCH] Error:', error);

      return {
        success: false,
        error: 'Search failed',
      };
    }
  },

  /**
   * Get student stats
   */
  getStats: async () => {
    try {
      const response = await api.get('/students/stats/');

      console.log('[STUDENTS][STATS] Success');

      return {
        success: true,
        data: response.data,
      };
    } catch (error) {
      console.error('[STUDENTS][STATS] Error:', error);

      return {
        success: false,
        error: 'Failed to fetch student stats',
      };
    }
  },
};

/**
 * ======================
 * ATTENDANCE API
 * ======================
 */
export const attendanceAPI = {
  /**
   * Recognize face from image
   */
  recognize: async (imageBase64) => {
    try {
      const response = await api.post('/attendance/recognize/', {
        image_base64: cleanBase64(imageBase64),
      });

      console.log('[ATTENDANCE][RECOGNIZE] Success:', response.data);

      return {
        success: true,
        data: response.data,
      };
    } catch (error) {
      // No match is expected behavior
      if (error.response?.status === 404) {
        console.log('[ATTENDANCE][RECOGNIZE] No match found');

        return {
          success: false,
          data: error.response.data,
          isNoMatch: true,
        };
      }

      const message =
        error.response?.data?.error ||
        'Recognition error';

      console.error('[ATTENDANCE][RECOGNIZE] Error:', message);

      return {
        success: false,
        error: message,
      };
    }
  },

  /**
   * Get today's attendance
   */
  getTodayLog: async () => {
    try {
      const response = await api.get('/attendance/');

      console.log('[ATTENDANCE][TODAY] Success');

      return {
        success: true,
        data: response.data,
      };
    } catch (error) {
      console.error('[ATTENDANCE][TODAY] Error:', error);

      return {
        success: false,
        error: 'Failed to fetch attendance log',
      };
    }
  },

  /**
   * Get attendance stats
   */
  getStats: async () => {
    try {
      const response = await api.get('/attendance/stats/');

      console.log('[ATTENDANCE][STATS] Success');

      return {
        success: true,
        data: response.data,
      };
    } catch (error) {
      console.error('[ATTENDANCE][STATS] Error:', error);

      return {
        success: false,
        error: 'Failed to fetch attendance stats',
      };
    }
  },

  /**
   * Get attendance status
   */
  getStatus: async () => {
    try {
      const response = await api.get('/attendance/status/');

      console.log('[ATTENDANCE][STATUS] Success');

      return {
        success: true,
        data: response.data,
      };
    } catch (error) {
      console.error('[ATTENDANCE][STATUS] Error:', error);

      return {
        success: false,
        error: 'Failed to fetch status',
      };
    }
  },

  /**
   * Get student attendance history
   */
  getHistory: async (studentId, days = 30) => {
    try {
      const response = await api.get('/attendance/student_history/', {
        params: {
          student_id: studentId,
          days,
        },
      });

      console.log('[ATTENDANCE][HISTORY] Success');

      return {
        success: true,
        data: response.data,
      };
    } catch (error) {
      console.error('[ATTENDANCE][HISTORY] Error:', error);

      return {
        success: false,
        error: 'Failed to fetch history',
      };
    }
  },
};

/**
 * ======================
 * EXPORT DEFAULT
 * ======================
 */
export default {
  studentsAPI,
  attendanceAPI,
};
